// Browser inventory is client-measured. The market owns escrow and all exchanges.
let marketState=null,marketRows=[],marketMode='list',marketKind='',marketRarity='',marketQuery='',marketFilterSide='offer',marketPage=0,marketNext=false,marketSelection=null,marketOffer=null,marketBusy=false,marketEpoch=0;
const marketKinds={gear:'装備',gem:'ジェム',material:'素材',gold:'ゴールド'};
const marketUUID=value=>typeof value==='string'&&/^[0-9a-f-]{36}$/.test(value);
const marketItemSave=saveItem;saveItem=(item,slot)=>{const out=marketItemSave(item,slot);if(out&&item.marketAssetId!==undefined){if(!marketUUID(item.marketAssetId))throw Error('市場の装備IDが不正です');out.marketAssetId=item.marketAssetId;}return out;};
const marketGemSave=saveGem;saveGem=gem=>{const out=marketGemSave(gem);if(gem.marketAssetId!==undefined){if(!marketUUID(gem.marketAssetId))throw Error('市場のジェムIDが不正です');out.marketAssetId=gem.marketAssetId;}return out;};
const marketSaveBase=validateSave;validateSave=data=>{const out=marketSaveBase(data),pending=data.p.marketPending;if(pending){if(!['deposit','withdraw'].includes(pending.kind)||!marketUUID(pending.body?.op)||typeof pending.account!=='string'||! /^[0-9a-f]{64}$/.test(pending.account)||JSON.stringify(pending).length>24000)throw Error('市場の処理履歴が不正です');out.p.marketPending=JSON.parse(JSON.stringify(pending));}return out;};
function marketIcon(asset){if(asset.kind==='gear'){const recipe=asset.item_key?.includes('@')?FORGE_RECIPES.find(r=>r.id===asset.item_key.split('@')[1]):null;return equipmentArt(asset.payload||(recipe?forgeRecipeItem(recipe):null),asset.item_key.split('@')[0]);}if(asset.kind==='gem')return gemIcon(asset.item_key);if(asset.kind==='material')return materialIcon(asset.item_key);return '<span class="market-gold">◈</span>';}
function marketName(a){return a.kind==='gear'&&!a.payload?(EQUIPMENT[a.item_key]?.label||a.name):a.name;}
function marketDescription(a){let h='<h3>'+gearEscape(marketName(a))+'</h3><p>× '+a.quantity.toLocaleString()+'</p>';if(a.kind==='gear'&&a.payload)h+=itemDetails(a.payload)+'<p>ソケット '+a.payload.sockets.map(s=>s.color).join(' · ')+' ／ リンク '+a.payload.links.filter(Boolean).length+'</p>';if(a.kind==='gem'&&a.payload)h+='<p>Lv '+a.payload.level+'</p><p>'+gearEscape(GEM[a.item_key]?.desc||'')+'</p>'+(a.payload.forged?'<p>属性：'+a.payload.forged.elements.map(i=>ELEMENTS[i].name).join('・')+'</p>':'');return h;}
function marketLocal(){return [...p.bag.filter(it=>!it.locked&&!it.sockets.some(s=>s.gem)).map(it=>({local:'bag:'+p.bag.indexOf(it),kind:'gear',item_key:it.slot,name:it.name,quantity:1,payload:it,rarity:it.rarity})),...p.gems.map((g,i)=>({local:'gem:'+i,kind:'gem',item_key:g.type,name:gemDisplayName(g),quantity:1,payload:g,rarity:g.forged?'rare':'normal'})),...Object.entries(campaign().materials).filter(([id,n])=>MATERIALS[id]&&n>0).map(([id,n])=>({local:'material:'+id,kind:'material',item_key:id,name:MATERIALS[id].name,quantity:n,rarity:['normal','magic','rare','rare'][+id.split(':')[1]]})),...(p.gold>0?[{local:'gold',kind:'gold',item_key:'gold',name:'ゴールド',quantity:p.gold,rarity:'normal'}]:[])];}
function marketCatalog(){return [...GEAR_SLOTS.map(slot=>({kind:'gear',item_key:slot,name:EQUIPMENT[slot].label,quantity:1})),...FORGE_RECIPES.map(r=>({kind:'gear',item_key:r.slot+'@'+r.id,name:r.name,quantity:1})),...Object.entries(GEM).map(([id,g])=>({kind:'gem',item_key:id,name:g.name,quantity:1})),...Object.entries(MATERIALS).map(([id,m])=>({kind:'material',item_key:id,name:m.name,quantity:1})),{kind:'gold',item_key:'gold',name:'ゴールド',quantity:1}];}
function marketMatches(a,l){return a.state==='available'&&a.kind===l.want_kind&&(a.item_key===l.want_key||a.kind==='gear'&&a.item_key+'@'+a.payload?.recipeId===l.want_key)&&a.quantity>=l.want_quantity&&(l.want_rarity==='any'||a.rarity===l.want_rarity);}
function marketWantAsset(l){return {kind:l.want_kind,item_key:l.want_key,name:l.want_name,quantity:l.want_quantity};}
async function showMarket(mode=marketMode){if(!started||!villageOpen){say('市場は村で利用できます');return;}if(!accountReady()){accountReturn=()=>showMarket(mode);showAccount();return;}if(tutorialState().active){say('初回の練習を終えてから利用できます');return;}marketMode=mode;const epoch=++marketEpoch;worldMenu('冒険者の市場','<p role="status">市場を読み込んでいます…</p><button onclick="showVillage()">村に戻る</button>','market');try{marketState=await rankingRequest('market/state');if(epoch!==marketEpoch||menuSurface!=='market')return;if(mode==='list'){const data=await rankingRequest('market/list?'+new URLSearchParams({q:marketQuery,kind:marketFilterSide==='offer'?marketKind:'',wanted:marketFilterSide==='wanted'?marketKind:'',rarity:marketRarity,page:marketPage}));if(epoch!==marketEpoch||menuSurface!=='market')return;marketRows=data.list;marketNext=data.hasNext;}else{let rows=mode==='vault'?marketState.assets:mode==='history'?marketState.mine:mode==='deposit'?marketLocal():marketCatalog();rows=rows.filter(row=>{const a=row.offer||row;return (!marketKind||a.kind===marketKind)&&(!marketRarity||a.rarity===marketRarity)&&(!marketQuery||marketName(a).includes(marketQuery));});marketNext=rows.length>(marketPage+1)*24;marketRows=rows.slice(marketPage*24,(marketPage+1)*24);}marketPaint();}catch(e){if(epoch===marketEpoch&&menuSurface==='market')worldMenu('冒険者の市場','<p>'+gearEscape(e.message)+'</p><button onclick="showMarket()">再試行</button><button onclick="showVillage()">村に戻る</button>','market');}}
function marketTab(mode){marketSelection=null;marketPage=0;marketKind='';marketRarity='';marketQuery='';showMarket(mode);}
function marketPaint(){const pending=p.marketPending;worldMenu('冒険者の市場','<div class="market-toolbar">'+[['list','募集を探す'],['vault','市場倉庫'],['deposit','品を預ける'],['history','自分の取引']].map(([id,label])=>'<button onclick="marketTab(\''+id+'\')" aria-pressed="'+(marketMode===id)+'">'+label+'</button>').join('')+'<button onclick="showVillage()">村に戻る</button></div>'+(pending?'<div class="market-notice"><p>受け渡し処理が未完了です。品は保留中です。</p><button onclick="marketResume()">受け渡しを再確認</button>'+(pending.kind==='deposit'?'<button onclick="marketResume(true)">預け入れを取り消す</button>':'')+'</div>':'')+'<div class="market-filters"><input id="marketSearch" aria-label="市場の名前検索" placeholder="品の名前で検索" maxlength="80" value="'+gearEscape(marketQuery)+'"><select aria-label="品の種類" onchange="marketKind=this.value;marketPage=0;showMarket()"><option value="">全種類</option>'+Object.entries(marketKinds).map(([id,n])=>'<option value="'+id+'" '+(marketKind===id?'selected':'')+'>'+n+'</option>').join('')+'</select><select aria-label="装備レア度" onchange="marketRarity=this.value;marketPage=0;showMarket()"><option value="">全レア度</option>'+[['normal','通常'],['magic','魔法'],['rare','希少']].map(([id,n])=>'<option value="'+id+'" '+(marketRarity===id?'selected':'')+'>'+n+'</option>').join('')+'</select><button onclick="marketQuery=$(\'marketSearch\').value;marketPage=0;showMarket()">検索</button></div>'+(marketMode==='wanted'?'<p>欲しい品を選択 → 右側で個数・条件を決定</p>':'')+'<div class="market-layout"><nav class="market-grid" aria-label="市場の品一覧">'+marketRows.map((row,i)=>{const a=row.offer||row;return '<button data-rarity="'+(a.rarity||'normal')+'" data-market-index="'+i+'" onclick="marketSelect('+i+',true)" aria-label="'+gearEscape(marketName(a)+' ×'+a.quantity)+'">'+marketIcon(a)+'<span>'+gearEscape(marketName(a))+'</span><b>× '+a.quantity.toLocaleString()+'</b>'+(row.want_kind?'<small>求：'+gearEscape(marketName(marketWantAsset(row)))+' ×'+row.want_quantity+'</small>':'')+'</button>';}).join('')+(marketRows.length?'':'<p>該当する品はありません</p>')+'</nav><section id="marketDetail" tabindex="-1" aria-live="polite"></section></div><div class="market-pagination"><button onclick="marketPage--;showMarket()" '+(!marketPage?'disabled':'')+'>前のページ</button><span>'+(marketPage+1)+'</span><button onclick="marketPage++;showMarket()" '+(!marketNext?'disabled':'')+'>次のページ</button></div><details><summary>市場の使い方</summary><p>① 品を市場倉庫へ預ける ② 倉庫の品から募集する ③ 欲しい品と個数を指定。交換成立後は市場倉庫から受け取れます。出品者はオフラインでも交換できます。</p><p>装備中・保護中・ジェム装着中の装備は預けられません。ジェムは先に取り外してください。市場倉庫150枠、同時募集10件まで。</p></details>','market');for(const b of $('card').querySelectorAll('[data-market-index]'))b.onfocus=()=>marketSelect(+b.dataset.marketIndex);if(marketMode==='list'){const side=document.createElement('select');side.setAttribute('aria-label','検索する品');side.innerHTML='<option value="offer">受け取る品から探す</option><option value="wanted">渡せる品から探す</option>';side.value=marketFilterSide;side.onchange=()=>{marketFilterSide=side.value;marketPage=0;showMarket();};$('card').querySelector('.market-filters').prepend(side);}if(marketRows.length)marketSelect(Math.min(marketSelection??0,marketRows.length-1));menuFocusElement($('card').querySelector('[data-market-index="'+(marketSelection??0)+'"]')||$('card').querySelector('button'));}
function marketQuantity(max=1000000){return '<label>個数 <input id="marketQuantity" type="number" min="1" max="'+Math.min(max,1000000)+'" value="1" inputmode="numeric"></label><div class="market-amounts">'+[-10,-1,1,10].map(n=>'<button onclick="$(\'marketQuantity\').value=clamp(Number($(\'marketQuantity\').value)+'+n+',1,'+Math.min(max,1000000)+')">'+(n>0?'+':'')+n+'</button>').join('')+'<button onclick="$(\'marketQuantity\').value='+Math.min(max,1000000)+'">最大</button></div>';}
function marketSelect(index,enter=false){const row=marketRows[index],box=$('marketDetail');if(!row||!box)return;marketSelection=index;const a=row.offer||row;let h=marketDescription(a);if(row.offer){const want=marketWantAsset(row);h='<div class="market-exchange-summary"><section><small>'+(row.mine?'渡す品':'受け取る品')+'</small>'+marketIcon(a)+'<strong>'+gearEscape(marketName(a))+'</strong><b>× '+a.quantity+'</b></section><section><small>'+(row.mine?'欲しい品':'渡す品')+'</small>'+marketIcon(want)+'<strong>'+gearEscape(marketName(want))+'</strong><b>× '+want.quantity+'</b></section></div><details><summary>品の性能・条件を見る</summary>'+marketDescription(a)+(row.want_rarity!=='any'?'<p>必要なレア度：'+({normal:'通常',magic:'魔法',rare:'希少'}[row.want_rarity]||'')+'</p>':'')+'</details>'+'<p>依頼主：'+gearEscape(row.seller)+' · '+({open:'募集中',completed:'交換成立',cancelled:'取消済み'}[row.state]||'')+'</p>';if(row.state==='open'&&row.mine)h+='<button onclick="marketAction(\'cancel\',{listingId:marketRows[marketSelection].id})">募集を取り消す</button>';else if(row.state==='open'){const matches=marketState.assets.filter(asset=>marketMatches(asset,row));h+='<h4>交換に使う市場倉庫の品</h4>'+matches.map(asset=>'<button class="market-payment" onclick="marketConfirmExchange(\''+asset.id+'\')">'+marketIcon(asset)+'<span>'+gearEscape(asset.name)+' · 所持×'+asset.quantity+' / 渡す×'+row.want_quantity+'</span></button>').join('')+(matches.length?'':'<p>条件に合う品を市場倉庫へ預けると交換できます。</p><button onclick="marketTab(\'deposit\')">品を預ける</button>');}}
 else if(marketMode==='vault')h+='<p>'+({available:'倉庫に保管中',escrow:'募集に預けています'}[a.state]||'')+'</p>'+(a.state==='available'?'<button onclick="marketStartListing()">この品で募集する</button><button onclick="marketWithdraw()">手元に受け取る</button>':'');
 else if(marketMode==='deposit')h+=(['gold','material'].includes(a.kind)?marketQuantity(a.quantity):'')+'<button onclick="marketDeposit()">市場倉庫へ預ける</button>';
 else if(marketMode==='wanted')h+=(['gold','material'].includes(a.kind)?marketQuantity():'')+(a.kind==='gear'?'<label>必要なレア度<select id="marketWantRarity"><option value="any">指定なし</option><option value="normal">通常</option><option value="magic">魔法</option><option value="rare">希少</option></select></label>':'')+'<p>渡す品：'+gearEscape(marketState.assets.find(x=>x.id===marketOffer)?.name||'')+'</p><button onclick="marketCreate()">この条件で募集を出す</button>';
 box.innerHTML=h;for(const b of $('card').querySelectorAll('[data-market-index]'))b.setAttribute('aria-pressed',String(+b.dataset.marketIndex===index));if(enter)menuFocusElement(box.querySelector('button:not(:disabled),input,select')||box);}
function marketStartListing(){marketOffer=marketRows[marketSelection].id;marketTab('wanted');}
async function marketAction(path,body){if(marketBusy)return;marketBusy=true;try{await rankingRequest('market/'+path,{op:crypto.randomUUID(),account:marketState.account,...body});say(path==='exchange'?'交換成立。市場倉庫に品が届きました':path==='create'?'募集を公開しました':'募集を取り消しました');await showMarket(path==='exchange'?'vault':'history');}catch(e){say(e.message);await showMarket();}finally{marketBusy=false;}}
function marketCreate(){const a=marketRows[marketSelection];if(!a||!marketOffer)return;marketAction('create',{assetId:marketOffer,want:{kind:a.kind,key:a.item_key,quantity:['gold','material'].includes(a.kind)?Number($('marketQuantity').value):1,rarity:$('marketWantRarity')?.value||'any'}});}
function marketConfirmExchange(assetId){const listing=marketRows[marketSelection],asset=marketState.assets.find(x=>x.id===assetId);if(!listing||!asset)return;const box=$('marketDetail');box.innerHTML='<h3>交換内容の確認</h3><p>渡す：'+gearEscape(asset.name)+' ×'+listing.want_quantity+'</p><p>受け取る：'+gearEscape(listing.offer.name)+' ×'+listing.offer.quantity+'</p><p>交換が成立すると取り消せません。</p><button id="marketExchangeConfirm">この内容で交換する</button><button onclick="marketSelect(marketSelection,true)">戻る</button>';$('marketExchangeConfirm').onclick=()=>marketAction('exchange',{listingId:listing.id,assetId});menuFocusElement($('marketExchangeConfirm'));}
function marketCanReceive(a){return a.kind==='gear'?p.bag.length<20:a.kind==='gem'?p.gems.length<20000:a.kind==='gold'?p.gold+a.quantity<=1e9:(campaign().materials[a.item_key]||0)+a.quantity<=1e7;}
function marketReceive(a){if(a.kind==='gear')p.bag.push({...saveItem(a.payload),marketAssetId:a.id});else if(a.kind==='gem')p.gems.push({...saveGem(a.payload),marketAssetId:a.id});else if(a.kind==='gold')p.gold+=a.quantity;else campaign().materials[a.item_key]=(campaign().materials[a.item_key]||0)+a.quantity;}
async function marketDeposit(){if(marketBusy||p.marketPending)return say('先に保留中の受け渡しを完了してください');const selected=marketRows[marketSelection],a=marketLocal().find(x=>x.local===selected?.local);if(!a)return;const quantity=['gold','material'].includes(a.kind)?Number($('marketQuantity')?.value):1;if(!Number.isInteger(quantity)||quantity<1||quantity>Math.min(a.quantity,1000000))return say('個数を確認してください');const payload=a.payload?(a.kind==='gear'?saveItem(a.payload):saveGem(a.payload)):null,asset={id:a.payload?.marketAssetId||crypto.randomUUID(),kind:a.kind,item_key:a.item_key,quantity,payload};if(!worldTransaction(()=>{if(a.kind==='gear')p.bag.splice(+a.local.split(':')[1],1);else if(a.kind==='gem')p.gems.splice(+a.local.split(':')[1],1);else if(a.kind==='gold')p.gold-=quantity;else campaign().materials[a.item_key]-=quantity;p.marketPending={kind:'deposit',account:marketState.account,body:{op:crypto.randomUUID(),asset}};}))return;await marketResume();}
async function marketWithdraw(){if(marketBusy||p.marketPending)return say('先に保留中の受け渡しを完了してください');const a=marketRows[marketSelection];if(!a||!marketCanReceive(a))return say('鞄や所持数の空きを確保してください');if(!worldTransaction(()=>p.marketPending={kind:'withdraw',account:marketState.account,body:{op:crypto.randomUUID(),assetId:a.id}}))return;await marketResume();}
async function marketResume(cancel=false){if(marketBusy||!p.marketPending||!accountReady())return;const pending=p.marketPending;if(pending.account!==marketState?.account)return say('この受け渡しを始めたアカウントでログインしてください');marketBusy=true;try{const data=await rankingRequest('market/'+pending.kind,{...pending.body,account:pending.account,...(cancel?{cancel:true}:{})});if(p.marketPending?.body.op!==pending.body.op)return;const asset=data.cancelled?pending.body.asset:data.asset;if(asset&&!marketCanReceive(asset))throw Error('受け取り待ちです。鞄や所持数の空きを確保してください');if(!worldTransaction(()=>{if(asset)marketReceive(asset);delete p.marketPending;}))throw Error('保存できません。受け渡しは保留しています');say(data.cancelled?'預け入れを取り消し、品を戻しました':'受け渡しが完了しました');await showMarket('vault');}catch(e){say(e.message);await showMarket();}finally{marketBusy=false;}}
const marketVillageBase=showVillage;showVillage=(...args)=>{const result=marketVillageBase(...args);if(menuSurface==='village'){const b=document.createElement('button');b.textContent='市場';b.onclick=()=>marketTab('list');($('card').querySelector('.panel-heading')||$('card')).append(b);}return result;};
const marketPauseBase=panel;panel=(kind,...args)=>{const r=marketPauseBase(kind,...args);if(kind==='pause'&&villageOpen){const b=document.createElement('button');b.textContent='市場';b.onclick=()=>marketTab('list');$('card').querySelector('.panel-body')?.append(b);}return r;};
const marketPadBase=padMenu;padMenu=(g,l,r,dt)=>{if(menuSurface==='market'&&padEdge(g,'back')){if(document.activeElement?.closest('#marketDetail'))menuFocusElement($('card').querySelector('[data-market-index="'+marketSelection+'"]'));else showVillage();return;}return marketPadBase(g,l,r,dt);};
const marketScrollBase=menuScroll;menuScroll=(stick,dt)=>{if(menuSurface==='market'){const pane=document.activeElement?.closest('.market-grid,#marketDetail');if(pane){pane.scrollTop+=stick.y*500*dt;return;}}return marketScrollBase(stick,dt);};
const marketRevealBase=menuReveal;menuReveal=el=>{const pane=el?.closest('.market-grid,#marketDetail');if(pane){menuRevealWithin(pane,el);return marketRevealBase(pane);}return marketRevealBase(el);};
